import json


def classify(line):
    """Return 'protocol-error <code>', 'tool-error' or 'ok' for one response line."""
    message = json.loads(line)
    if "error" in message:
        return f"protocol-error {message['error']['code']}"
    if message["result"].get("isError", False):
        return "tool-error"
    return "ok"

